import{_ as n,o as i,c as r,a2 as t}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Detaillierte Erläuterung des Raumjurisprudenz-Dispositionssystems","description":"","frontmatter":{},"headers":[],"relativePath":"de/0013-空间法理调度体系详解.md","filePath":"de/0013-空间法理调度体系详解.md"}'),s={name:"de/0013-空间法理调度体系详解.md"};function u(d,e,a,l,o,h){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="detaillierte-erlauterung-des-raumjurisprudenz-dispositionssystems" tabindex="-1">Detaillierte Erläuterung des Raumjurisprudenz-Dispositionssystems <a class="header-anchor" href="#detaillierte-erlauterung-des-raumjurisprudenz-dispositionssystems" aria-label="Permalink to &quot;Detaillierte Erläuterung des Raumjurisprudenz-Dispositionssystems&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>13</td></tr><tr><td>Modul</td><td>Kosmische Gesetze und Kultivierungssysteme</td></tr><tr><td>Schlüsselwörter</td><td>Raumjurisprudenz, Gesetzesdisposition, Ebenendurchquerung, Isolierter Raum, Drei Ursprungsgrundlagen</td></tr></tbody></table><h2 id="i-systemubersicht" tabindex="-1">I. Systemübersicht <a class="header-anchor" href="#i-systemubersicht" aria-label="Permalink to &quot;I. Systemübersicht&quot;">​</a></h2><p>Das Raumjurisprudenz-Dispositionssystem ist das dritte der dreihundert Ursprungs-Kultivierungssysteme, steht an dritter Stelle unter den &quot;Drei Ursprungsgrundlagen&quot; und ist die Grundlage aller Kultivierungssysteme und technologischen Anwendungen, die Raum-, Dimensions- und Ebenenoperationen betreffen. Dieses System nimmt die &quot;Verständnis und Disposition der Raumgesetze&quot; als Kern, betont die präzise Wahrnehmung und geordnete Steuerung der Raumjurisprudenz,而非 einfaches und grobes Raumreißen und -zerstören. Das Raumjurisprudenz-Dispositionssystem ist die Kultivierungsgrundlage für wichtige Anwendungen wie interdimensionale Interaktion, Konstruktion isolierter Räume, Replikspiegel-Technologie und Ankerwartung und spielt eine unersetzliche Rolle im Infrastrukturaufbau der symbiotischen Zivilisation.</p><p>Das Raumjurisprudenz-Dispositionssystem eignet sich für Kultivierende mit starker Raumwahrnehmung, präzisem logischem Denken und Wertschätzung von Präzision und Ordnung. Die Kultivierenden dieses Systems sind die wichtigste technische Talentgruppe in der symbiotischen Zivilisation und übernehmen Schlüsselaufgaben wie Ankerbau, Wartung von Ebenenkanälen, Verwaltung isolierter Räume und Konstruktion archäologischer Räume.</p><h2 id="ii-kernprinzip-des-systems" tabindex="-1">II. Kernprinzip des Systems <a class="header-anchor" href="#ii-kernprinzip-des-systems" aria-label="Permalink to &quot;II. Kernprinzip des Systems&quot;">​</a></h2><p>Das Kernprinzip des Raumjurisprudenz-Dispositionssystems ist &quot;Raum ist Jurisprudenz, Disposition ist Ordnung&quot;, das aus drei Ebenen verstanden werden kann:</p><h3 id="_2-1-die-jurisprudenzielle-essenz-des-raums" tabindex="-1">2.1 Die jurisprudenzielle Essenz des Raums <a class="header-anchor" href="#_2-1-die-jurisprudenzielle-essenz-des-raums" aria-label="Permalink to &quot;2.1 Die jurisprudenzielle Essenz des Raums&quot;">​</a></h3><p>In der Weltanschauung des Heng Yuan Zhou ist der Raum kein leerer Behälter, sondern eine geordnete Struktur, die aus einer Reihe jurisprudenzieller Regeln besteht. Attribute wie Dimension, Distanz, Richtung, Krümmung und Stabilität des Raums werden alle durch die zugrundeliegenden raumjurisprudenziellen Regeln bestimmt. Die Essenz des Raums zu verstehen bedeutet, den Funktionsmechanismus dieser jurisprudenziellen Regeln zu verstehen.</p><p>Die Raumjurisprudenz kann in drei Ebenen unterteilt werden: Grundjurisprudenz (bestimmt die grundlegenden Attribute des Raums, wie dreidimensionale Struktur, Distanzdefinition usw.), Wandeljurisprudenz (bestimmt die Veränderlichkeit des Raums, wie Raumfaltung, Krümmungsänderung usw.), Ursprungsjurisprudenz (bestimmt die Schöpfung und Zerstörung des Raums, wie Bildung und Kollaps von Ebenen usw.). Die Kultivierung des Raumjurisprudenz-Dispositionssystems beginnt mit dem Verständnis der Grundjurisprudenz und vertieft sich schrittweise in die Wandeljurisprudenz und die Ursprungsjurisprudenz.</p><h3 id="_2-2-die-kernmethode-der-disposition" tabindex="-1">2.2 Die Kernmethode der Disposition <a class="header-anchor" href="#_2-2-die-kernmethode-der-disposition" aria-label="Permalink to &quot;2.2 Die Kernmethode der Disposition&quot;">​</a></h3><p>&quot;Disposition&quot; ist die Kernmethodologie des Raumjurisprudenz-Dispositionssystems. Im Gegensatz zum &quot;Raumreißen&quot; bei der räuberischen Kultivierung zerstört die Disposition die Raumstruktur nicht mit Gewalt, sondern führt durch das Verständnis und die Befolgung der Raumjurisprudenz eine geordnete Anpassung und Steuerung des Raums durch.</p><p>Die Kernmethoden der Disposition umfassen:</p><ul><li><strong>Jurisprudenzielle Wahrnehmung</strong>: den Funktionszustand der jurisprudenziellen Regeln im Raum wahrnehmen, die Struktur und Anomalien des Raums identifizieren</li><li><strong>Jurisprudenzielle Lenkung</strong>: durch die eigene Energie und das Bewusstsein die Raumjurisprudenz in die erwartete Richtung lenken</li><li><strong>Jurisprudenzielle Resonanz</strong>: mit der Raumjurisprudenz Resonanz erzeugen, die Wirkung und den Reichweite der Disposition verstärken</li><li><strong>Jurisprudenzielle Stabilisierung</strong>: die Ergebnisse der Disposition in stabile Raumstrukturen stabilisieren, wie isolierte Räume, Ebenenkanäle usw.</li></ul><p>Der Schlüssel zur Disposition liegt im &quot;Handeln gemäß der Tendenz&quot;. Der Kultivierende ist nicht der Herr des Raums, sondern der &quot;Disponent&quot; der Raumjurisprudenz — durch das Verständnis und die Befolgung der Jurisprudenz实现 er die geordnete Steuerung des Raums.</p><h3 id="_2-3-ethische-prinzipien-der-raumoperation" tabindex="-1">2.3 Ethische Prinzipien der Raumoperation <a class="header-anchor" href="#_2-3-ethische-prinzipien-der-raumoperation" aria-label="Permalink to &quot;2.3 Ethische Prinzipien der Raumoperation&quot;">​</a></h3><p>Das Raumjurisprudenz-Dispositionssystem hat strenge ethische Prinzipien für Raumoperationen festgelegt:</p><ul><li><strong>Prinzip der minimalen Intervention</strong>: Operationen am Raum sollten so klein wie möglich sein, um unnötige Zerstörung der Raumstruktur zu vermeiden</li><li><strong>Prinzip der Wiederherstellbarkeit</strong>: Alle temporären Raumoperationen müssen nach Abschluss den ursprünglichen Zustand des Raums wiederherstellen, keine dauerhaften Schäden hinterlassen</li><li><strong>Prinzip der Isolation</strong>: Raumoperationen, die Risiken erzeugen können, müssen in isolierten Räumen durchgeführt werden, um die Ausbreitung von Risiken zu verhindern</li><li><strong>Prinzip der Genehmigung</strong>: Hochstufige Raumoperationen (wie Ebenendurchquerung, Raumfaltung usw.) müssen die Genehmigung der Ankerverwaltungsinstitution durchlaufen</li></ul><h2 id="iii-reichseinteilung-und-merkmale-jeder-phase" tabindex="-1">III. Reichseinteilung und Merkmale jeder Phase <a class="header-anchor" href="#iii-reichseinteilung-und-merkmale-jeder-phase" aria-label="Permalink to &quot;III. Reichseinteilung und Merkmale jeder Phase&quot;">​</a></h2><p>Das Raumjurisprudenz-Dispositionssystem ist in fünf Kernreiche unterteilt:</p><table tabindex="0"><thead><tr><th>Reich</th><th>Name</th><th>Kernmerkmal</th><th>Raumsteuerungsreichweite</th><th>Markante Fähigkeit</th></tr></thead><tbody><tr><td>Erstes Reich</td><td>Raumerkennung</td><td>Nimmt anfänglich die Existenz der Raumjurisprudenz wahr, kann die Grundstruktur des Raums identifizieren</td><td>Wahrnehmungsreichweite hundert Meter</td><td>Raumwahrnehmung: kann den jurisprudenziellen Zustand und die Anomalien des umgebenden Raums wahrnehmen</td></tr><tr><td>Zweites Reich</td><td>Raumsteuerung</td><td>Kann grundlegende Raumsteuerung durchführen, wie Kurzstrecken-Raumverschiebung</td><td>Steuerungsreichweite zehn Meter</td><td>Kurzstrecken-Teleportation: kann Raumverschiebung innerhalb von zehn Metern durchführen</td></tr><tr><td>Drittes Reich</td><td>Raumtransformation</td><td>Kann lokale Attribute des Raums verändern, wie Raumfaltung, Krümmungsanpassung</td><td>Steuerungsreichweite hundert Meter</td><td>Raumfaltung: kann eine Distanz von hundert Metern zu einer Schrittweite falten</td></tr><tr><td>Viertes Reich</td><td>Jurisprudenzraum</td><td>Kann stabile Raumstrukturen aufbauen, wie isolierte Räume, Speicherräume</td><td>Steuerungsreichweite Kilometer</td><td>Konstruktion isolierter Räume: kann stabile unabhängige Räume für Kultivierung oder Experimente schaffen</td></tr><tr><td>Fünftes Reich</td><td>Ursprungsraum</td><td>Berührt die Ursprungsjurisprudenz des Raums, kann Ebenendurchquerung und Ebenenkanalkonstruktion durchführen</td><td>Steuerungsreichweite inter-dimensional</td><td>Ebenendurchquerung: kann mit Unterstützung von Ankern eine stabile interdimensionale Durchquerung durchführen</td></tr></tbody></table><p>Der Durchbruch jedes Reichs erfordert das Bestehen der &quot;Raumjurisprudenz-Prüfung&quot;: Es werden die Tiefe des Verständnisses des Kultivierenden für die Raumjurisprudenz, die Präzision und Stabilität der Raumsteuerung sowie die Einhaltung der ethischen Grundsätze der Raumoperation bewertet; nur wenn alle drei Punkte den Standard erreichen, kann die Erhöhung des Reichs bestätigt werden.</p><h2 id="iv-kernkultivierungsmethoden-des-systems" tabindex="-1">IV. Kernkultivierungsmethoden des Systems <a class="header-anchor" href="#iv-kernkultivierungsmethoden-des-systems" aria-label="Permalink to &quot;IV. Kernkultivierungsmethoden des Systems&quot;">​</a></h2><h3 id="_4-1-methode-der-jurisprudenziellen-wahrnehmungskultivierung" tabindex="-1">4.1 Methode der jurisprudenziellen Wahrnehmungskultivierung <a class="header-anchor" href="#_4-1-methode-der-jurisprudenziellen-wahrnehmungskultivierung" aria-label="Permalink to &quot;4.1 Methode der jurisprudenziellen Wahrnehmungskultivierung&quot;">​</a></h3><p>Die jurisprudenzielle Wahrnehmung ist die Grundlage des Raumjurisprudenz-Dispositionssystems und umfasst:</p><ul><li><strong>Methode des stillen Raumhörens</strong>: In einem stillen Raum die Augen schließen und den Geist konzentrieren, das feine Funktionieren der Raumjurisprudenz wahrnehmen, als würde man den Atem des Raums &quot;hören&quot;</li><li><strong>Methode der Anomalieerkennung</strong>: Wahrnehmungstraining in Bereichen mit Raumanomalien (wie Raumrisse, Krümmungsanomalien usw.) durchführen, die Fähigkeit zur Erkennung von Raumanomalien verbessern</li><li><strong>Methode der mehrdimensionalen Wahrnehmung</strong>: Schrittweise das Wahrnehmen von Raumstrukturen jenseits der drei Dimensionen trainieren, um die Grundlage für das Verständnis der hochdimensionalen Raumjurisprudenz zu schaffen</li><li><strong>Methode der Jurisprudenzkarte</strong>: Die wahrgenommene raumjurisprudenzielle Struktur zu einer &quot;Jurisprudenzkarte&quot; im Bewusstsein zeichnen, um die allgemeine Kognition der Raumstruktur zu verbessern</li></ul><h3 id="_4-2-methode-der-raumsteuerungskultivierung" tabindex="-1">4.2 Methode der Raumsteuerungskultivierung <a class="header-anchor" href="#_4-2-methode-der-raumsteuerungskultivierung" aria-label="Permalink to &quot;4.2 Methode der Raumsteuerungskultivierung&quot;">​</a></h3><p>Die Raumsteuerung ist die Kernfähigkeit des Systems und umfasst:</p><ul><li><strong>Methode des Mikrooperationstrainings</strong>: Beginnt das Training mit der kleinsten Raumsteuerung, wie dem Falten eines Zentimeters Raums, und verbessert schrittweise die Präzision und den Reichweite der Steuerung</li><li><strong>Methode der Verschiebungskultivierung</strong>: Beginnt mit Kurzstrecken-Raumverschiebungen, erhöht schrittweise die Distanz und Komplexität der Verschiebung, und实现 schließlich kontinuierliche Teleportation</li><li><strong>Methode der Faltungskultivierung</strong>: Trainiert die Fähigkeit der Raumfaltung, von einfachen geradlinigen Faltungen bis zu komplexen mehrdimensionalen Faltungen</li><li><strong>Methode der Krümmungskultivierung</strong>: Trainiert die Fähigkeit zur Anpassung der Raumkrümmung; die Krümmungssteuerung ist die Grundlage der hochstufigen Raumtechnologie</li></ul><h3 id="_4-3-methode-der-raumkonstruktionskultivierung" tabindex="-1">4.3 Methode der Raumkonstruktionskultivierung <a class="header-anchor" href="#_4-3-methode-der-raumkonstruktionskultivierung" aria-label="Permalink to &quot;4.3 Methode der Raumkonstruktionskultivierung&quot;">​</a></h3><p>Die Raumkonstruktion ist die hochstufige Fähigkeit des Systems und umfasst:</p><ul><li><strong>Methode der Speicherraumkonstruktion</strong>: Erlernt den Aufbau kleiner stabiler Speicherräume und beherrscht die Technologie der Raumgrenzenstabilisierung</li><li><strong>Methode der Konstruktion isolierter Räume</strong>: Erlernt den Aufbau unabhängiger Räume mit Isolationswirkung und beherrscht die Technologie von Raumbarrieren und Energieisolation</li><li><strong>Methode der Kultivierraumkonstruktion</strong>: Erlernt den Aufbau spezieller Räume, die für die Kultivierung geeignet sind, wie Kultivierungsräume mit unterschiedlichem Zeitfluss, Kultivierungsfelder mit einstellbarer Energiekonzentration usw.</li><li><strong>Methode der Ebenenkanalkonstruktion</strong>: Mit Unterstützung von Ankern erlernt man den Aufbau stabiler Kanäle, die zwei Ebenen verbinden</li></ul><h2 id="v-anwendungen-des-systems-in-der-symbiotischen-zivilisation" tabindex="-1">V. Anwendungen des Systems in der symbiotischen Zivilisation <a class="header-anchor" href="#v-anwendungen-des-systems-in-der-symbiotischen-zivilisation" aria-label="Permalink to &quot;V. Anwendungen des Systems in der symbiotischen Zivilisation&quot;">​</a></h2><p>Das Raumjurisprudenz-Dispositionssystem hat breite und wichtige Anwendungen in der symbiotischen Zivilisation:</p><h3 id="_5-1-infrastrukturaufbau" tabindex="-1">5.1 Infrastrukturaufbau <a class="header-anchor" href="#_5-1-infrastrukturaufbau" aria-label="Permalink to &quot;5.1 Infrastrukturaufbau&quot;">​</a></h3><ul><li><strong>Ankerbau und -wartung</strong>: Die hochstufigen Kultivierenden des Raumjurisprudenz-Dispositionssystems sind die Kernkraft beim Ankerbau und verantwortlich für das Design und die Konstruktion der Ankerraumstruktur</li><li><strong>Wartung von Ebenenkanälen</strong>: Wartung der Raumkanäle, die die verschiedenen Ebenen verbinden, um die Stabilität und Sicherheit der Kanäle zu gewährleisten</li><li><strong>Aufbau öffentlicher Kultivierräume</strong>: Aufbau spezieller Raumeinrichtungen wie öffentliche Kultivierungsräume, Jurisprudenz-Wahrnehmungsräume usw.</li></ul><h3 id="_5-2-archaologie-und-forschung" tabindex="-1">5.2 Archäologie und Forschung <a class="header-anchor" href="#_5-2-archaologie-und-forschung" aria-label="Permalink to &quot;5.2 Archäologie und Forschung&quot;">​</a></h3><ul><li><strong>Replikspiegel-Fernarchäologie</strong>: Die Kultivierenden der Raumjurisprudenz beteiligen sich an der Raumkonstruktion der Replikspiegel-Technologie und bieten isolierte Fernräume für die Archäologie</li><li><strong>Experimente in isolierten Räumen</strong>: Bereitstellung isolierter Räume für gefährliche Jurisprudenzexperimente und Energieexperimente, um die Ausbreitung von Risiken zu verhindern</li><li><strong>Erforschung alter Räume</strong>: Erforschung der Raumstrukturen und Raumtechnologien, die von alten Zivilisationen hinterlassen wurden</li></ul><h3 id="_5-3-anwendungen-im-alltag" tabindex="-1">5.3 Anwendungen im Alltag <a class="header-anchor" href="#_5-3-anwendungen-im-alltag" aria-label="Permalink to &quot;5.3 Anwendungen im Alltag&quot;">​</a></h3><ul><li><strong>Raumspeichertechnologie</strong>: Bereitstellung von Raumspeichergeräten für die breite Bevölkerung, um das tägliche Leben zu erleichtern</li><li><strong>Raummedizin</strong>: Nutzung der Raumtechnologie zur Durchführung präziser medizinischer Operationen, wie nicht-invasive Chirurgie, Entfernung von inneren Läsionen usw.</li><li><strong>Raumtransport</strong>: Kurzstrecken-Transportsysteme basierend auf der Raumfaltungstechnologie, die die Reiseeffizienz erheblich verbessern</li></ul><h3 id="_5-4-sicherheit-und-verteidigung" tabindex="-1">5.4 Sicherheit und Verteidigung <a class="header-anchor" href="#_5-4-sicherheit-und-verteidigung" aria-label="Permalink to &quot;5.4 Sicherheit und Verteidigung&quot;">​</a></h3><ul><li><strong>Raumbarrieren</strong>: Aufbau von Raumbarrieren zum Schutz wichtiger Einrichtungen</li><li><strong>Raumblockade</strong>: In Notfällen Raumblockaden in bestimmten Bereichen durchführen, um die Ausbreitung von Gefahren zu verhindern</li><li><strong>Raumrettung</strong>: Nutzung der Raumverschiebungsfähigkeit zur Durchführung von Notrettungen, wie die schnelle Evakuierung von Personen aus Katastrophengebieten</li></ul><h2 id="vi-vorteile-und-grenzen-des-systems" tabindex="-1">VI. Vorteile und Grenzen des Systems <a class="header-anchor" href="#vi-vorteile-und-grenzen-des-systems" aria-label="Permalink to &quot;VI. Vorteile und Grenzen des Systems&quot;">​</a></h2><h3 id="_6-1-vorteile" tabindex="-1">6.1 Vorteile <a class="header-anchor" href="#_6-1-vorteile" aria-label="Permalink to &quot;6.1 Vorteile&quot;">​</a></h3><ul><li>Extrem hoher praktischer Wert, ist ein unentbehrliches Kernsystem für den Infrastrukturaufbau der Zivilisation</li><li>Die Raumsteuerungsfähigkeit hat enorme Vorteile in Kampfszenarien, Erkundung, Rettung usw.</li><li>Die Kultivierenden haben einen hohen sozialen Status, mit reichlichen Beschäftigungs- und Entwicklungsmöglichkeiten</li><li>Enge Verbindung mit technologischen Anwendungen, die Kultivierungsergebnisse können direkt in technologische Produkte umgewandelt werden</li><li>Nach der Verbesserung der Raumwahrnehmungsfähigkeit hat sie auch eine unterstützende Rolle bei der Kultivierung anderer Systeme</li></ul><h3 id="_6-2-grenzen" tabindex="-1">6.2 Grenzen <a class="header-anchor" href="#_6-2-grenzen" aria-label="Permalink to &quot;6.2 Grenzen&quot;">​</a></h3><ul><li>Hat gewisse Anforderungen an das Talent der Raumwahrnehmung, nicht alle Rassen sind für die Praxis geeignet</li><li>Die Erhöhung der Kampfkraft in der Anfangsphase ist nicht offensichtlich, die Hauptfähigkeiten neigen zur Unterstützung und Technologie</li><li>Hochstufige Raumoperationen haben ein relativ hohes Risiko, Operationsfehler können schwerwiegende Folgen wie Raumrisse verursachen</li><li>Der Durchbruch der hochstufigen Reiche erfordert die Unterstützung von Ankern, in Gebieten mit unzureichender Ankerabdeckung ist die Kultivierung schwierig</li><li>Der Kultivierungsprozess ist relativ eintönig und erfordert eine große Menge an präzisem Steuerungstraining</li></ul><h2 id="vii-kompatibilitat-mit-anderen-systemen" tabindex="-1">VII. Kompatibilität mit anderen Systemen <a class="header-anchor" href="#vii-kompatibilitat-mit-anderen-systemen" aria-label="Permalink to &quot;VII. Kompatibilität mit anderen Systemen&quot;">​</a></h2><p>Das Raumjurisprudenz-Dispositionssystem hat eine gute Kompatibilität mit anderen Systemen, insbesondere:</p><ul><li>Gleichzeitige Kultivierung mit dem Deduktionsiterationssystem: kann verschiedene Anwendungsweisen der Raumjurisprudenz deduzieren, die Präzision und Innovation der Raumsteuerung verbessern</li><li>Gleichzeitige Kultivierung mit dem Lebenszyklussystem: kann spezielle Räume für den Lebensenergiezyklus aufbauen, die Effizienz der Lebenszykluskultivierung verbessern</li><li>Gleichzeitige Kultivierung mit Systemen der Kategorie Bewusstseinserhöhung: Das Verständnis der Raumjurisprudenz hilft bei der Wahrnehmung und Anpassung des Bewusstseins an hochdimensionale Räume</li><li>Gleichzeitige Kultivierung mit Systemen der Kategorie Angewandte Ingenieurwissenschaft: Die Raumjurisprudenztechnologie ist ein wichtiger Zweig der Jurisprudenzingenieurwissenschaft, die gleichzeitige Kultivierung kann die Ingenieurfähigkeit erheblich verbessern</li></ul><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Das Raumjurisprudenz-Dispositionssystem ist der &quot;Raumgrundstein&quot; der Anker-Symbiotischen Zivilisation. Es basiert auf dem tiefen Verständnis der Raumjurisprudenz und nutzt die geordnete Disposition als Methode, um der Zivilisation unentbehrliche raumtechnologische Unterstützung für interdimensionale Interaktion, Infrastrukturaufbau, wissenschaftliche Forschung und Alltagsanwendungen zu bieten. Das ultimative Ziel des Raumjurisprudenz-Dispositionssystems ist es, jeden Kultivierenden zum &quot;Wächter und Erbauer&quot; des kosmischen Raums zu machen, und auf der Grundlage des Verständnisses der Raumjurisprudenz ein kosmisches Raumnetzwerk aufzubauen, das geordneter, vernetzter und sicherer ist.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Gesamtübersicht der Dreihundert Ursprungs-Kultivierungssysteme)</li><li>62-空间法理技术实现 (Raumjurisprudenz-Technologieimplementierung)</li><li>64-隔离空间构建技术 (Technologie zur Konstruktion isolierter Räume)</li></ul>',54)])])}const c=n(s,[["render",u]]);export{g as __pageData,c as default};
